// Original invented scale readings; finite teaching model, not physical calibration.
const records=(prefix,values)=>values.map((value,i)=>({id:`${prefix}${i+1}`,value}));
export const newReferenceView=()=>({v:1,referenceShown:false,adjustmentShown:false,adjustment:0,checkShown:false});
export function referenceScaleSource(){
 return {v:1,id:'reference-scales',model:'reference-scales-v1',title:'Two model scales at the bakery',origin:'Original invented scale readings for this learning activity.',notice:'Not physical measurements or a calibration certificate.',purpose:'Compare agreement between readings and closeness to a model reference, while keeping original records.',axis:{max:150,tick:25},groups:[{id:'blue',label:'Blue scale',records:records('blue',[111,112,113])},{id:'copper',label:'Copper scale',records:records('copper',[94,100,106])}],referenceScales:{v:1,unit:'g',reference:100,adjustableGroupId:'blue',adjustment:{min:-20,max:20},check:{reference:50,groups:[{id:'blue',label:'Blue scale',records:records('check-blue',[61,62,63])},{id:'copper',label:'Copper scale',records:records('check-copper',[44,50,56])}]},copy:{intro:'The baker is comparing two made-up scale records. Do close-together readings have to be close to the right amount? These are invented readings in grams. The reference amount is given by this model, not measured by the game. In this model, each list repeats the same item on its one scale in the same conditions. Both scales read that shared item.',checkIntro:'These new lists repeat a different shared item, again in the same model conditions. Now use the same adjustment with these separately invented readings.',limit:'This changes a numerical preview, not a scale or the original readings. Two model examples do not show that an adjustment works for every mass or for a real scale.',reflection:'Tell someone what the original lists and your preview show. What would you still want to check?'},teaching:{steps:['Different example: the model reference is 20 g. Readings 25, 26, 27 g have mean 26 g and range 2 g.','The mean is (25 + 26 + 27) ÷ 3 = 26 g. It is 6 g above the model reference.','Add −6 g to every reading: 19, 20, 21 g. The mean becomes 20 g; the range stays 2 g.','A different list, 14, 20, 26 g, also has mean 20 g but range 12 g. A matching mean does not make every reading exact.'],factsByStep:[[],[],[],[]]},glossary:[{term:'Precision',meaning:'How closely repeated readings agree under stated conditions.'},{term:'Accuracy',meaning:'How close a reading is to a reference value.'},{term:'Reference',meaning:'The comparison value given by this model.'},{term:'Adjustment',meaning:'A number added to each reading in a separate preview.'},{term:'Range',meaning:'Highest reading minus lowest reading.'}]}};
}
